import React from 'react';
import { 
  CheckCircle2, 
  Circle, 
  Clock, 
  TrendingUp, 
  Target, 
  ArrowRight,
  AlertCircle
} from 'lucide-react';
import { DayData, Task, Category } from '../types';

interface DashboardProps {
  dayData: DayData;
  toggleTask: (day: number, taskId: string) => void;
  skipTask: (day: number, taskId: string) => void;
  currentDay: number;
}

const Dashboard: React.FC<DashboardProps> = ({ 
  dayData, 
  toggleTask, 
  skipTask, 
  currentDay 
}) => {
  const categories: Category[] = [
    'Morning Routine', 
    'English Learning', 
    'Trading', 
    'Coding/DSA', 
    'Flutter/React', 
    'Night Review'
  ];

  const phaseInfo = {
    1: { title: "Phase 1: Foundation & Focus", desc: "Flutter Focus", range: "Day 1-30", color: "from-blue-600 to-cyan-500 shadow-blue-500/20" },
    2: { title: "Phase 2: Fullstack Expansion", desc: "Flutter + React Intro", range: "Day 31-60", color: "from-indigo-600 to-purple-500 shadow-indigo-500/20" },
    3: { title: "Phase 3: Integration & Mastery", desc: "Full Stack + Trading Mastery", range: "Day 61-180", color: "from-purple-600 to-pink-500 shadow-purple-500/20" }
  };

  const getPhase = (day: number) => {
    if (day <= 30) return phaseInfo[1];
    if (day <= 60) return phaseInfo[2];
    return phaseInfo[3];
  };

  const phase = getPhase(currentDay);
  const completedTasks = dayData.tasks.filter(t => t.completed).length;
  const totalTasks = dayData.tasks.length;
  const progressPercent = Math.round((completedTasks / totalTasks) * 100);

  const quotes = [
    "The secret of getting ahead is getting started.",
    "Small daily improvements are the key to long-term results.",
    "Don't stop when you're tired, stop when you're done.",
    "Discipline is choosing between what you want now and what you want most.",
    "Action is the foundational key to all success."
  ];

  const randomQuote = quotes[currentDay % quotes.length];

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-8 animate-fade-in">
      {/* Top Header Section */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div className="space-y-1">
          <h2 className="text-sm font-bold tracking-widest text-blue-400 uppercase">Challenge Dashboard</h2>
          <div className="flex items-center gap-3">
            <h1 className="text-4xl font-bold tracking-tight">Day {currentDay} of 180</h1>
            <div className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider bg-gradient-to-r ${phase.color} text-white shadow-lg`}>
              {phase.range}
            </div>
          </div>
          <p className="text-slate-400 font-medium">
            {new Date(dayData.date).toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
          </p>
        </div>

        <div className="glass-card p-5 bg-gradient-to-br from-white/5 to-white/0 flex items-center gap-6">
          <div className="relative w-16 h-16">
            <svg className="progress-ring w-16 h-16">
              <circle className="text-white/5" stroke="currentColor" strokeWidth="4" fill="transparent" r="28" cx="32" cy="32" />
              <circle 
                className="progress-ring-circle text-blue-500 drop-shadow-[0_0_8px_rgba(59,130,246,0.5)]" 
                stroke="currentColor" strokeWidth="4" 
                strokeDasharray={`${2 * Math.PI * 28}`} 
                strokeDashoffset={`${2 * Math.PI * 28 * (1 - progressPercent / 100)}`} 
                strokeLinecap="round" fill="transparent" r="28" cx="32" cy="32" 
              />
            </svg>
            <div className="absolute inset-0 flex items-center justify-center">
              <span className="text-xs font-bold">{progressPercent}%</span>
            </div>
          </div>
          <div>
            <p className="text-[10px] uppercase tracking-wider text-slate-400 mb-0.5">Tasks Completed</p>
            <p className="text-2xl font-bold flex items-baseline gap-1">
              {completedTasks} <span className="text-sm text-slate-500">/ {totalTasks}</span>
            </p>
          </div>
        </div>
      </div>

      {/* Hero Quote Card */}
      <div className="relative overflow-hidden rounded-3xl p-8 bg-gradient-to-r from-blue-600/20 to-purple-600/20 border border-white/10 shadow-2xl">
        <div className="absolute -right-20 -bottom-20 w-80 h-80 bg-blue-500/10 blur-[100px]" />
        <div className="absolute -left-20 -top-20 w-60 h-60 bg-purple-500/10 blur-[80px]" />
        <div className="relative z-10 space-y-4">
          <div className="flex items-center gap-2">
            <TrendingUp size={18} className="text-blue-400" />
            <h3 className="font-bold text-lg">{phase.title}</h3>
          </div>
          <p className="text-2xl font-medium text-slate-100 italic">"{randomQuote}"</p>
          <div className="flex items-center gap-4 text-xs font-semibold text-slate-400">
            <span className="flex items-center gap-1.5"><Target size={14} /> {phase.desc}</span>
            <span className="w-1 h-1 bg-slate-600 rounded-full" />
            <span className="flex items-center gap-1.5"><Clock size={14} /> Goal: 100% Consistency</span>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left Column: Tasks */}
        <div className="lg:col-span-2 space-y-8">
          {categories.map((cat) => {
            const catTasks = dayData.tasks.filter(t => t.category === cat);
            if (catTasks.length === 0) return null;
            return (
              <section key={cat} className="space-y-4">
                <div className="flex items-center justify-between px-2">
                  <h3 className="text-lg font-bold flex items-center gap-2 text-slate-200">
                    <div className="w-1.5 h-1.5 bg-blue-500 rounded-full shadow-[0_0_8px_rgba(59,130,246,0.8)]" />
                    {cat}
                  </h3>
                  <span className="text-[10px] uppercase tracking-widest font-bold text-slate-500">
                    {catTasks.filter(t => t.completed).length} of {catTasks.length} Done
                  </span>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {catTasks.map((task) => (
                    <div 
                      key={task.id} 
                      className={`glass-card p-4 group transition-all duration-300 relative overflow-hidden ${
                        task.completed ? 'opacity-80 border-blue-500/20' : 'hover:scale-[1.02]'
                      }`}
                    >
                      {task.completed && (
                         <div className="absolute top-0 right-0 p-1 opacity-20">
                           <CheckCircle2 size={48} className="text-blue-500" />
                         </div>
                      )}
                      <div className="flex items-start justify-between gap-4 mb-3">
                        <div className="space-y-1">
                          <p className={`font-semibold text-sm leading-snug ${task.completed ? 'text-blue-400 line-through' : 'text-slate-100'}`}>
                            {task.title}
                          </p>
                          <div className="flex items-center gap-1.5 text-[10px] font-medium text-slate-500">
                            <Clock size={10} /> {task.time}
                          </div>
                        </div>
                        <button 
                          onClick={() => toggleTask(currentDay, task.id)}
                          className={`flex-shrink-0 transition-all duration-300 ${
                            task.completed 
                              ? 'text-blue-500 scale-110 shadow-[0_0_15px_rgba(59,130,246,0.5)]' 
                              : 'text-slate-600 hover:text-slate-400'
                          }`}
                        >
                          {task.completed ? <CheckCircle2 size={24} /> : <Circle size={24} />}
                        </button>
                      </div>
                      <div className="flex items-center justify-between mt-auto">
                        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${
                          task.completed ? 'bg-blue-500/10 text-blue-400' : 'bg-white/5 text-slate-500'
                        }`}>
                          +{task.points} PTS
                        </span>
                        {!task.completed && (
                          <button 
                            onClick={(e) => { e.stopPropagation(); skipTask(currentDay, task.id); }}
                            className={`text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full border transition-colors ${
                              task.skipped 
                                ? 'bg-orange-500/10 text-orange-400 border-orange-500/20' 
                                : 'text-slate-500 border-white/5 hover:border-slate-600'
                            }`}
                          >
                            {task.skipped ? 'Skipped' : 'Skip'}
                          </button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </section>
            );
          })}
        </div>

        {/* Right Column: Schedule & Quick Stats */}
        <div className="space-y-8">
           <div className="glass-card p-6 bg-gradient-to-br from-white/5 to-white/0 border-white/10">
             <h3 className="text-lg font-bold mb-6 flex items-center justify-between">
                Standard Schedule
                <div className="px-2 py-0.5 bg-blue-500/10 text-blue-500 rounded-md text-[10px]">DAILY</div>
             </h3>
             <div className="space-y-6 relative ml-2 border-l border-white/5 pb-2">
                {[
                  { time: '06:00', task: 'Morning Flow', icon: Clock },
                  { time: '07:00', task: 'English Practice', icon: Clock },
                  { time: '09:00', task: 'Live Trading', icon: Clock },
                  { time: '19:00', task: 'Trade Review', icon: Clock },
                  { time: '21:00', task: 'DSA & Dev', icon: Clock },
                  { time: '23:30', task: 'Night Review', icon: Clock }
                ].map((item, i) => (
                  <div key={i} className="relative pl-6">
                    <div className="absolute -left-[4.5px] top-1.5 w-2 h-2 rounded-full border border-dark-primary bg-blue-400 shadow-[0_0_8px_rgba(59,130,246,0.8)]" />
                    <p className="text-[10px] font-bold text-slate-500 mb-0.5">{item.time} AM/PM</p>
                    <p className="text-sm font-semibold text-slate-200">{item.task}</p>
                  </div>
                ))}
             </div>
           </div>

           <div className="glass-card p-6 bg-orange-600/10 border-orange-500/20">
              <div className="flex items-center gap-3 mb-4">
                <div className="w-10 h-10 rounded-xl bg-orange-600/20 flex items-center justify-center text-orange-500">
                  <AlertCircle size={20} />
                </div>
                <div>
                  <h4 className="font-bold text-orange-100">Critical Rule</h4>
                  <p className="text-xs text-orange-400/80 uppercase font-bold tracking-tighter">Penalties Apply</p>
                </div>
              </div>
              <p className="text-sm text-slate-300 leading-relaxed">
                Missing core sessions like <span className="text-orange-400 font-bold">Trading</span> or <span className="text-orange-400 font-bold">Dev</span> will result in a <span className="text-orange-400 font-bold">-10 PTS</span> deduction. Stay consistent to earn bonuses!
              </p>
           </div>

           <button 
             onClick={() => window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' })}
             className="w-full glass-card p-5 group flex items-center justify-between bg-blue-600/10 border-blue-500/20 hover:bg-blue-600/20"
           >
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-blue-600/20 flex items-center justify-center text-blue-400">
                  <ArrowRight size={20} />
                </div>
                <div className="text-left">
                  <h4 className="font-bold text-white">Review & Plan</h4>
                  <p className="text-[10px] text-blue-400 uppercase font-bold tracking-widest">Available after 9PM</p>
                </div>
              </div>
              <ArrowRight size={20} className="text-blue-500 group-hover:translate-x-1 transition-transform" />
           </button>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
